var controller = UnityEngine.Object.FindFirstObjectByType<GameOfLife.LifeController>();
var view = controller.View;
var root = view.BoardImage.transform;
var overlay = root.GetChild(0).GetComponent<UnityEngine.UI.RawImage>();
var board = root.GetChild(1).GetComponent<UnityEngine.UI.RawImage>();
var border = root.GetChild(2).GetComponent<GameOfLife.LifeSelectionGraphic>();
var pixels = ((UnityEngine.Texture2D)board.texture).GetRawTextureData<UnityEngine.Color32>();
int transparent = 0, white = 0, other = 0;
for (int i = 0; i < pixels.Length; i += 31)
{
    var pixel = pixels[i];
    if (pixel.a == 0 && pixel.r == 0 && pixel.g == 0 && pixel.b == 0) transparent++;
    else if (pixel.a == 255 && pixel.r == 255 && pixel.g == 255 && pixel.b == 255) white++;
    else other++;
}
view.SetSelection(true, view.Origin + view.VisibleCells / 4,
    view.Origin + view.VisibleCells * 3 / 4);
UnityEngine.Canvas.ForceUpdateCanvases();
var mesh = border.canvasRenderer.GetMesh();
int vertices = mesh.vertexCount;
int triangleIndices = mesh.triangles.Length;
view.SetSelection(controller.HasSelection, controller.SelectionMin, controller.SelectionMax);
UnityEngine.Canvas.ForceUpdateCanvases();
return new { boardTextureWidth = board.texture.width, boardTextureHeight = board.texture.height,
    overlayTextureWidth = overlay.texture.width, sampledEveryPixels = 31, transparent, white, other,
    selectionVertices = vertices, selectionTriangleIndices = triangleIndices,
    overlayIndex = overlay.transform.GetSiblingIndex(), boardIndex = board.transform.GetSiblingIndex(),
    selectionIndex = border.transform.GetSiblingIndex(), rootColor = view.BoardImage.color };
